import assert from 'node:assert/strict';
import { writeFile } from 'node:fs/promises';
export function createGuard({ verifyFrozen, remote, claimPath, record }) {
  let armed = null, calls = 0;
  return {
    arm(plan) {
      assert.equal(calls, 0);
      assert.equal(plan.maximumNativeCalls, 1);
      const p = plan.inputParameters;
      assert.deepEqual(p, { IV_UNIT_KEY: 'KG', IV_LANGUAGE: '1', IV_EXPECTED_VERSION: (plan.originalVersion[0] === '0' ? '1' : '0') + plan.originalVersion.slice(1), IV_SET_MSEHT: '', IV_MSEHT: '', IV_SET_MSEHL: 'X', IV_MSEHL: '千克', IV_REQUEST: 'GR2K923429', IV_TASK: 'GR2K923430' });
      armed = structuredClone(p);
    },
    disarm() { armed = null; },
    get calls() { return calls; },
    async invoke(connection, request) {
      await verifyFrozen();
      assert.equal(connection, 'w200');
      if (['Z_ORVANTA_CFG_UNIT_READ', 'RFC_READ_TABLE', 'BBP_RFC_READ_TABLE'].includes(request.functionName)) {
        await record({ kind: 'read', functionName: request.functionName });
        return remote(connection, request);
      }
      assert.equal(request.functionName, 'Z_ORVANTA_CFG_UNIT_APPLY', 'FUNCTION_OUTSIDE_APPROVED_PROBE');
      assert.ok(armed, 'NATIVE_PROBE_NOT_ARMED');
      assert.equal(calls, 0, 'NATIVE_PROBE_ALREADY_DISPATCHED');
      assert.deepEqual(request.inputParameters, armed);
      await writeFile(claimPath, JSON.stringify({ at: new Date().toISOString(), parameters: armed }), { flag: 'wx' });
      calls++;
      await record({ kind: 'native', functionName: request.functionName, calls });
      return remote(connection, request);
    }
  };
}

