import { test } from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join, resolve, sep } from 'node:path';
import { createGuard } from './guard.mjs';
const version = 'a'.repeat(64);
const plan = { maximumNativeCalls: 1, originalVersion: version, inputParameters: { IV_UNIT_KEY: 'KG', IV_LANGUAGE: '1', IV_EXPECTED_VERSION: '0' + version.slice(1), IV_SET_MSEHT: '', IV_MSEHT: '', IV_SET_MSEHL: 'X', IV_MSEHL: '千克', IV_REQUEST: 'GR2K923429', IV_TASK: 'GR2K923430' } };
const request = { functionName: 'Z_ORVANTA_CFG_UNIT_APPLY', inputParameters: plan.inputParameters };
async function withGuard(action) {
  const dir = await mkdtemp(join(tmpdir(), 'r37-guard-')); let calls = 0;
  const options = { verifyFrozen: async () => {}, remote: async () => { calls++; return 'native'; }, claimPath: join(dir, 'claim.json'), record: async () => {} };
  const guard = createGuard(options);
  try { await action(guard, () => calls, options); } finally { assert.ok(resolve(dir).startsWith(resolve(tmpdir()) + sep)); await rm(dir, { recursive: true, force: true }); }
}
test('unarmed writer never dispatches', () => withGuard(async (guard, count) => { await assert.rejects(guard.invoke('w200', request)); assert.equal(count(), 0); }));
test('other function / system never dispatches', () => withGuard(async (guard, count) => { guard.arm(plan); await assert.rejects(guard.invoke('w300', request)); await assert.rejects(guard.invoke('w200', { functionName: 'BAPI_TRANSACTION_COMMIT' })); assert.equal(count(), 0); }));
test('different business value refused before arm', () => withGuard(async (guard, count) => { assert.throws(() => guard.arm({ ...plan, inputParameters: { ...plan.inputParameters, IV_MSEHL: 'different' } })); assert.equal(count(), 0); }));
test('correct version refused before arm', () => withGuard(async (guard, count) => { assert.throws(() => guard.arm({ ...plan, inputParameters: { ...plan.inputParameters, IV_EXPECTED_VERSION: version } })); assert.equal(count(), 0); }));
test('modified armed inputs never dispatch', () => withGuard(async (guard, count) => { guard.arm(plan); await assert.rejects(guard.invoke('w200', { ...request, inputParameters: { ...plan.inputParameters, IV_TASK: 'GR2K923431' } })); assert.equal(count(), 0); }));
test('single dispatch and persistent restart refusal', () => withGuard(async (guard, count, options) => { guard.arm(plan); assert.equal(await guard.invoke('w200', request), 'native'); await assert.rejects(guard.invoke('w200', request)); const restarted = createGuard(options); restarted.arm(plan); await assert.rejects(restarted.invoke('w200', request)); assert.equal(count(), 1); }));
test('frozen integrity failure never dispatches', () => withGuard(async (_guard, count, options) => { const guard = createGuard({ ...options, verifyFrozen: async () => { throw Error('FROZEN_CHANGED'); } }); guard.arm(plan); await assert.rejects(guard.invoke('w200', request), /FROZEN_CHANGED/); assert.equal(count(), 0); }));
test('read-only native reader allowed without arming', () => withGuard(async (guard, count) => { assert.equal(await guard.invoke('w200', { functionName: 'Z_ORVANTA_CFG_UNIT_READ' }), 'native'); assert.equal(count(), 1); assert.equal(guard.calls, 0); }));

