import { readFile, writeFile, rename } from 'node:fs/promises';
import { watch } from 'node:fs';
import { createHash } from 'node:crypto';
import assert from 'node:assert/strict';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import { createGuard } from './guard.mjs';
const root = 'C:/My/Workplace/Coding/vscode-abap/abap-mcp-standalone';
const stage = root + '/.cache/unit-native-stale-r37';
const hash = bytes => createHash('sha256').update(bytes).digest('hex');
let pinnedManifestFingerprint;
async function verifyFrozen() {
  const bytes = await readFile(stage + '/frozen.json');
  if (pinnedManifestFingerprint) assert.equal(hash(bytes), pinnedManifestFingerprint, 'Frozen manifest changed');
  const manifest = JSON.parse(bytes);
  for (const [path, expected] of Object.entries(manifest.files)) assert.equal(hash(await readFile(stage + '/' + path)), expected, path);
  return hash(bytes);
}
const manifestFingerprint = await verifyFrozen();
pinnedManifestFingerprint = manifestFingerprint;
if (!process.env.ABAP_MCP_W200_PASSWORD) throw Error('Password missing; no SAP call made.');
const { TOOL_NAMES } = await import('./runtime/dist/src/tool-registry.js');
const allowedTools = ['get_runtime_info', 'read_function_module_interface', 'read_configuration_unit', 'inspect_configuration_transport'];
assert.ok(allowedTools.every(n => TOOL_NAMES.includes(n)));
process.env.ABAP_MCP_TOOL_PROFILE = 'full';
process.env.ABAP_MCP_TOOL_DENY = TOOL_NAMES.filter(n => !allowedTools.includes(n)).join(',');
const [{ AdtBackend }, { loadConnections }, { startHttpServer }, { ToolService }, safety, { WriteOperationReceiptStore }] = await Promise.all(['adt-backend', 'config', 'http', 'tools', 'configuration-unit-native-safety', 'write-operation-receipts'].map(n => import('./runtime/dist/src/' + n + '.js')));
const connections = (await loadConnections(root + '/.cache/landscape-acceptance/connections.json')).filter(c => c.id === 'w200');
assert.equal(connections.length, 1); assert.equal(connections[0].client, '200'); assert.equal(connections[0].username.toUpperCase(), 'WYS');
const backend = new AdtBackend(connections);
const metrics = { startedAt: new Date().toISOString(), events: [], nativeWriterCalls: 0 };
const guard = createGuard({ verifyFrozen, remote: backend.callRemoteFunction.bind(backend), claimPath: stage + '/native.claim.json', record: async event => { metrics.events.push({ at: new Date().toISOString(), ...event }); metrics.nativeWriterCalls = guard.calls; await writeFile(stage + '/metrics.json', JSON.stringify(metrics, null, 2)); } });
backend.callRemoteFunction = guard.invoke.bind(guard);
await writeFile(stage + '/metrics.json', JSON.stringify(metrics, null, 2), { flag: 'wx' });
const service = new ToolService(backend, stage + '/exports');
const shared = new Client({ name: 'r37-existing-approved-readonly-lock-route', version: 'r37' });
await shared.connect(new StreamableHTTPClientTransport(new URL('http://127.0.0.1:4849/mcp')));
const sharedTools = (await shared.listTools()).tools;
assert.equal(sharedTools.find(t => t.name === 'search_sap_locks')?.annotations?.readOnlyHint, true);
const observations = [];
async function observed(kind, action) {
  const data = await action(); observations.push({ kind, at: new Date().toISOString(), data });
  await writeFile(stage + '/observations.json', JSON.stringify(observations, null, 2));
  return data;
}
const readers = {
  readDefinition: () => observed('writer_definition', async () => JSON.parse(await service.readFunctionModuleInterface({ connectionId: 'w200', functionName: 'Z_ORVANTA_CFG_UNIT_APPLY' }))),
  readUnit: () => observed('native_unit', async () => JSON.parse(await service.readConfigurationUnit({ connectionId: 'w200', unitKey: 'KG', language: 'ZH', includeApiSnapshot: true }))),
  inspectTransport: () => observed('CTS', async () => JSON.parse(await service.inspectConfigurationTransport({ connectionId: 'w200', requestNumber: 'GR2K923429', taskNumber: 'GR2K923430', unitText: { unitKey: 'KG', language: 'ZH' } }))),
  readLocks: argument => observed('shared_approved_locks', async () => {
    assert.ok(['*T006*', '*GR2K923429*', '*GR2K923430*'].includes(argument));
    const reply = await shared.callTool({ name: 'search_sap_locks', arguments: { connectionId: 'w200', username: 'WYS', argument, maxResults: 100 } }, undefined, { timeout: 120000 });
    assert.notEqual(reply.isError, true);
    return JSON.parse(reply.content.filter(p => p.type === 'text').map(p => p.text).join('\n'));
  })
};
async function atomic(name, data) {
  await writeFile(stage + '/' + name + '.tmp', JSON.stringify(data, null, 2), { flag: 'wx' });
  await rename(stage + '/' + name + '.tmp', stage + '/' + name);
}
const server = await startHttpServer(backend, 0, stage + '/state');
await atomic('ready.json', { pid: process.pid, url: server.mcpUrl, startedAt: new Date().toISOString(), revision: 'r37', allowedTools, manifestFingerprint, nativeLimit: 1, publicWriteTools: 0 });
console.log('Fixed r37 isolated MCP ready: ' + server.mcpUrl);
let busy = false, closing = false;
const handled = new Set();
async function handle(name) {
  if (name === 'stop.request' && !busy) return close();
  if (!['prepare.request.json', 'execute.request.json'].includes(name) || handled.has(name) || busy) return;
  handled.add(name); busy = true;
  try {
    await verifyFrozen();
    const request = JSON.parse(await readFile(stage + '/' + name, 'utf8'));
    if (name === 'prepare.request.json') {
      const deps = [];
      for (const functionName of ['Z_ORVANTA_CFG_UNIT_APPLY', 'Z_ORVANTA_CFG_UNIT_READ', 'UPDATE_T006A', 'TR_REQ_CHECK_OBJECT', 'TRINT_APPEND_TO_COMM_ARRAYS', 'TR_REQ_CHECK_KEY', 'CALCULATE_HASH_FOR_CHAR']) {
        const actual = JSON.parse(await service.readFunctionModuleInterface({ connectionId: 'w200', functionName }));
        const prior = JSON.parse(await readFile(stage + '/dependencies/' + functionName + '.definition.json', 'utf8'));
        assert.equal(actual.sourceFingerprint, prior.sourceFingerprint); assert.equal(actual.interfaceFingerprint, prior.interfaceFingerprint);
        deps.push({ functionName, sourceFingerprint: actual.sourceFingerprint, interfaceFingerprint: actual.interfaceFingerprint });
      }
      const plan = await safety.prepareNativeUnitStale(request, readers);
      assert.deepEqual(plan.beforeText, { MANDT: '200', SPRAS: '1', MSEHI: 'KG', MSEH3: 'KG', MSEH6: '公斤', MSEHT: '公斤', MSEHL: '千克' });
      assert.ok(plan.locks.every(l => l.status === 'no_observed_locks'));
      await atomic('prepared.json', { plan, dependencies: deps, manifestFingerprint });
    } else {
      const prepared = JSON.parse(await readFile(stage + '/prepared.json', 'utf8'));
      assert.deepEqual(request, { scenario: 'native_locked_stale_version', planFingerprint: prepared.plan.planFingerprint, acknowledgeOneNativeCall: true });
      guard.arm(prepared.plan);
      try {
        const result = await safety.runApprovedNativeUnitStale(prepared.plan, request, readers, backend, new WriteOperationReceiptStore(stage + '/probe-state'));
        await atomic('result.json', { result, manifestFingerprint, metrics });
      } finally { guard.disarm(); }
    }
  } catch (error) {
    await atomic(name.replace('.request.json', '.error.json'), { at: new Date().toISOString(), stage: name, code: /^[A-Z][A-Z0-9_]{0,100}$/.test(error.message) ? error.message : 'R37_PRECONDITION_OR_OBSERVATION_FAILED', firstErrorHash: hash(String(error)), nativeWriterCalls: guard.calls });
    console.error('R37 phase stopped; inspect safe evidence. No automatic retry.');
  } finally { busy = false; }
}
const watcher = watch(stage, (_event, name) => { void handle(name).catch(() => { console.error('Evidence persistence failed; no automatic retry.'); }); });
async function close() { if (closing) return; closing = true; watcher.close(); await shared.close(); await server.closeIfIdle(); process.exit(0); }
process.once('SIGINT', () => void close()); process.once('SIGTERM', () => void close());

