import { readFile, writeFile, rename, access } from 'node:fs/promises';
import { setTimeout as delay } from 'node:timers/promises';
import assert from 'node:assert/strict';
import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StreamableHTTPClientTransport } from '@modelcontextprotocol/sdk/client/streamableHttp.js';
import { prepareUnitStaleViaMcp, validateUnitSafetyEndpoint } from './runtime/scripts/probe-unit-native-stale.mjs';
const stage = 'C:/My/Workplace/Coding/vscode-abap/abap-mcp-standalone/.cache/unit-native-stale-r37';
const doc = 'C:/My/Workplace/Coding/vscode-abap/.doc';
const proof = { revision: 'r37', startedAt: new Date().toISOString(), mode: 'approved_single_native_stale_rejection', publicWriteTools: 0, maximumNativeCalls: 1, automaticRetry: false, automaticRestore: false };
async function exists(path) { try { await access(path); return true; } catch { return false; } }
async function command(name, data) { await writeFile(stage + '/' + name + '.tmp', JSON.stringify(data), { flag: 'wx' }); await rename(stage + '/' + name + '.tmp', stage + '/' + name); }
async function waitFor(name, failure) {
  const deadline = Date.now() + 240000;
  while (Date.now() < deadline) {
    if (await exists(stage + '/' + name)) return JSON.parse(await readFile(stage + '/' + name, 'utf8'));
    if (failure && await exists(stage + '/' + failure)) { proof.driverFailure = JSON.parse(await readFile(stage + '/' + failure, 'utf8')); throw Error('R37_DRIVER_STOPPED'); }
    await delay(1000);
  }
  throw Error('R37_OBSERVATION_TIMEOUT_NO_RETRY');
}
const client = new Client({ name: 'r37-fixed-mcp-native-stale-acceptance', version: 'r37' });
try {
  proof.runtime = await waitFor('ready.json');
  await client.connect(new StreamableHTTPClientTransport(validateUnitSafetyEndpoint(proof.runtime.url)));
  proof.tools = (await client.listTools()).tools;
  assert.equal(proof.tools.length, 4);
  assert.ok(proof.tools.every(t => t.annotations?.readOnlyHint === true));
  const input = { connectionId: 'w200', unitKey: 'KG', language: 'ZH', requestNumber: 'GR2K923429', taskNumber: 'GR2K923430', operationId: 'unit-native-stale-' + new Date().toISOString().replace(/[^0-9]/g, '') + '-r37' };
  await command('prepare.request.json', input);
  proof.prepared = await waitFor('prepared.json', 'prepare.error.json');
  proof.mcpPlan = await prepareUnitStaleViaMcp(client, input);
  assert.equal(proof.mcpPlan.planFingerprint, proof.prepared.plan.planFingerprint);
  assert.deepEqual(proof.mcpPlan.beforeText, proof.prepared.plan.beforeText);
  await command('execute.request.json', { scenario: 'native_locked_stale_version', planFingerprint: proof.prepared.plan.planFingerprint, acknowledgeOneNativeCall: true });
  proof.execution = await waitFor('result.json', 'execute.error.json');
  proof.status = proof.execution.result.status;
  assert.equal(proof.execution.result.status, 'native_stale_rejection_verified');
  assert.equal(proof.execution.metrics.nativeWriterCalls, 1);
} catch (error) {
  proof.status ??= 'Partially Verified'; proof.error = /^[A-Z][A-Z0-9_]{0,100}$/.test(error.message) ? error.message : 'R37_ACCEPTANCE_INCOMPLETE'; process.exitCode = 1;
} finally {
  await client.close();
  proof.finishedAt = new Date().toISOString();
  await writeFile(doc + '/orvanta-unit-native-stale-acceptance-20261004-r37.json', JSON.stringify(proof, null, 2), { flag: 'wx' });
}
console.log(JSON.stringify({ status: proof.status, nativeWriterCalls: proof.execution?.metrics?.nativeWriterCalls ?? proof.driverFailure?.nativeWriterCalls ?? 0, nativeCode: proof.execution?.result?.nativeCode ?? null, error: proof.error ?? null }));

