$ErrorActionPreference = 'Stop'
Set-Location -LiteralPath 'C:\My\Workplace\Coding\vscode-abap\abap-mcp-standalone'
try {
  Write-Host 'Approved single native stale-version rejection: w200 / 200 / wys.'
  Write-Host 'KG Chinese values stay unchanged. No retries, restores or transport releases.'
  $stalePassword = Read-Host -AsSecureString 'Enter SAP password (temporary process environment only)'
  if ($null -eq $stalePassword -or $stalePassword.Length -eq 0) { throw 'Empty password; no SAP call made.' }
  $staleCredential = [PSCredential]::new('unused', $stalePassword)
  $env:ABAP_MCP_W200_PASSWORD = $staleCredential.GetNetworkCredential().Password
  $staleCredential = $null
  $stalePassword = $null
  & node '.cache/unit-native-stale-r37/server.mjs'
  if ($LASTEXITCODE -ne 0) { throw "Isolated probe exited: $LASTEXITCODE" }
} catch {
  Write-Host $_.Exception.Message
  Read-Host 'Press Enter to close'
} finally {
  [Environment]::SetEnvironmentVariable('ABAP_MCP_W200_PASSWORD', $null, 'Process')
}
